open! Core
open! Hardcaml
open! Hardcaml_waveterm
open! Hardcaml_test_harness
module Day03 = Hardcaml_demo_project.Day03
module Harness = Cyclesim_harness.Make (Day03.I) (Day03.O)

let ( <--. ) = Bits.( <--. )

let input = In_channel.read_all "/Users/noah/Documents/code/ocaml/Hardcaml_template_project/input/day03a.txt"
let sample_input_values = (List.map ~f:(int_of_char) (String.to_list input));;

let simple_testbench (sim : Harness.Sim.t) =
  let inputs = Cyclesim.inputs sim in
  let outputs = Cyclesim.outputs sim in
  let cycle ?n () = Cyclesim.cycle ?n sim in
  (* Helper function for inputting one value *)
  let feed_input n =
    inputs.data_in <--. n;
    inputs.data_in_valid := Bits.vdd;
    cycle ();
    inputs.data_in_valid := Bits.gnd;
    cycle ()
  in
  (* Reset the design *)
  inputs.clear := Bits.vdd;
  cycle ();
  inputs.clear := Bits.gnd;
  cycle ();
  (* Pulse the start signal *)
  inputs.start := Bits.vdd;
  cycle ();
  inputs.start := Bits.gnd;
  (* Input some data *)
  List.iter sample_input_values ~f:(fun x -> feed_input x);
  inputs.finish := Bits.vdd;
  cycle ();
  inputs.finish := Bits.gnd;
  cycle ();

  while not (Bits.to_bool !(outputs.answer1.valid)) do
    cycle ()
  done;
  let answer1 = Bits.to_signed_int !(outputs.answer1.value) in
  let answer2 = Bits.to_signed_int !(outputs.answer2.value) in
  print_s [%message "Result" (answer1 : int) (answer2 : int)];
  cycle ~n:2 ()
;;

let waves_config = Waves_config.no_waves

let%expect_test "Simple test, optionally saving waveforms to disk" =
  Harness.run_advanced ~waves_config ~create:Day03.hierarchical simple_testbench;
  [%expect {| (Result (answer1 0) (answer2 2851181577568)) |}]
;;

let%expect_test "Simple test with printing waveforms directly" =
  let display_rules =
    [ Display_rule.port_name_matches
        ~wave_format:(Bit_or Int)
        (Re.Glob.glob "day03*" |> Re.compile)
    ]
  in
  Harness.run_advanced
    ~create:Day03.hierarchical
    ~trace:`All_named
    ~print_waves_after_test:(fun waves ->
      Waveform.print
        ~display_rules
        ~signals_width:36
        ~display_width:220
        ~wave_width:1
        waves)
    simple_testbench;
  [%expect
